package com.portfolio.dto;
import jakarta.validation.constraints.*; import java.math.BigDecimal; import java.time.LocalDate;
public class PortfolioDto {
 @NotBlank @Pattern(regexp="PORT\\d{4}") private String portfolioId; @NotBlank @Pattern(regexp="\\d{10}") private String accountNo; @NotBlank private String clientName; @NotBlank private String clientType; @NotNull private LocalDate createDate; private String status; private BigDecimal totalValue; private BigDecimal cashBalance; private String accountType; private String branchId; private String currencyCode; private String riskLevel;
 public String getPortfolioId(){return portfolioId;} public void setPortfolioId(String v){portfolioId=v;} public String getAccountNo(){return accountNo;} public void setAccountNo(String v){accountNo=v;} public String getClientName(){return clientName;} public void setClientName(String v){clientName=v;} public String getClientType(){return clientType;} public void setClientType(String v){clientType=v;} public LocalDate getCreateDate(){return createDate;} public void setCreateDate(LocalDate v){createDate=v;} public String getStatus(){return status;} public void setStatus(String v){status=v;} public BigDecimal getTotalValue(){return totalValue;} public void setTotalValue(BigDecimal v){totalValue=v;} public BigDecimal getCashBalance(){return cashBalance;} public void setCashBalance(BigDecimal v){cashBalance=v;} public String getAccountType(){return accountType;} public void setAccountType(String v){accountType=v;} public String getBranchId(){return branchId;} public void setBranchId(String v){branchId=v;} public String getCurrencyCode(){return currencyCode;} public void setCurrencyCode(String v){currencyCode=v;} public String getRiskLevel(){return riskLevel;} public void setRiskLevel(String v){riskLevel=v;}
}
